-- Payments in test mode (M9). Amounts are paise (integers). Prices come from
-- public.packages, never from code. Invoices are generated by ops per patient and
-- calendar month (India time): one line per completed visit at the package price,
-- the actual cab/auto fare per trip (pass-through), and the package's monthly fee.
-- Payment providers are adapters in the `payments` Edge Function (`test` by default).
-- Card/UPI details never touch this database; providers return ids only.

insert into public.app_settings (key, value, description) values
  ('billable_trip_statuses', '["completed"]',
   'Trip statuses billed as a visit (no-show billing is a founder decision; not billed by default)');

create type public.invoice_status as enum ('draft', 'issued', 'paid', 'void');
create type public.invoice_line_kind as enum ('visit', 'fare', 'monthly_fee');
create type public.payment_status as enum ('created', 'captured', 'failed');

create table public.invoices (
  id uuid primary key default gen_random_uuid(),
  patient_id uuid not null references public.patients (id) on delete cascade,
  package_id uuid not null references public.packages (id),
  period_start date not null,
  period_end date not null,
  status public.invoice_status not null default 'draft',
  total_paise integer not null default 0 check (total_paise >= 0),
  created_by uuid references public.profiles (id),
  created_at timestamptz not null default now(),
  issued_at timestamptz,
  paid_at timestamptz,
  unique (patient_id, period_start),
  check (period_end >= period_start)
);

create table public.invoice_lines (
  id bigint generated always as identity primary key,
  invoice_id uuid not null references public.invoices (id) on delete cascade,
  kind public.invoice_line_kind not null,
  trip_id uuid references public.trips (id) on delete set null,
  service_date date,
  amount_paise integer not null check (amount_paise >= 0)
);
create index invoice_lines_invoice_idx on public.invoice_lines (invoice_id);

create table public.payments (
  id uuid primary key default gen_random_uuid(),
  invoice_id uuid not null references public.invoices (id) on delete cascade,
  provider text not null check (provider in ('test', 'razorpay')),
  amount_paise integer not null check (amount_paise > 0),
  status public.payment_status not null default 'created',
  provider_order_id text unique,
  provider_payment_id text unique,
  created_by uuid references public.profiles (id),
  created_at timestamptz not null default now(),
  captured_at timestamptz
);
create index payments_invoice_idx on public.payments (invoice_id);

-- Reads only through the functions below; no direct grants for app roles.
revoke all on public.invoices, public.invoice_lines, public.payments from anon, authenticated;
alter table public.invoices enable row level security;
alter table public.invoice_lines enable row level security;
alter table public.payments enable row level security;

create trigger invoices_audit after insert or update or delete on public.invoices
  for each row execute function private.audit_row_change();
create trigger payments_audit after insert or update on public.payments
  for each row execute function private.audit_row_change();

-- Fares ---------------------------------------------------------------------------

-- Ops records the actual cab/auto fare for a trip (passed through at cost).
create function public.ops_record_trip_fare(p_trip_id uuid, p_fare_paise integer)
returns void
language plpgsql volatile security definer set search_path = ''
as $$
declare
  v_trip public.trips;
begin
  perform private.assert_ops();
  if p_fare_paise is null or p_fare_paise < 0 or p_fare_paise > 1000000 then
    raise exception 'fare must be between 0 and 1000000 paise' using errcode = '22023';
  end if;
  select * into v_trip from public.trips where id = p_trip_id for update;
  if not found then
    raise exception 'trip % not found', p_trip_id using errcode = 'P0002';
  end if;
  if exists (
    select 1 from public.invoice_lines l join public.invoices i on i.id = l.invoice_id
    where l.trip_id = p_trip_id and i.status in ('issued', 'paid')
  ) then
    raise exception 'trip is on an issued invoice' using errcode = '22023';
  end if;
  update public.trips set fare_amount_paise = p_fare_paise, updated_at = now() where id = p_trip_id;
  perform private.write_audit('record_trip_fare', 'trips', p_trip_id::text, v_trip.patient_id,
    jsonb_build_object('fare_paise', p_fare_paise));
end;
$$;

-- Invoices ------------------------------------------------------------------------

-- Builds (or rebuilds, while draft) the invoice for one patient and calendar month.
create function public.ops_generate_invoice(p_patient_id uuid, p_month date)
returns uuid
language plpgsql volatile security definer set search_path = ''
as $$
declare
  v_start date := date_trunc('month', p_month)::date;
  v_end date := (date_trunc('month', p_month) + interval '1 month - 1 day')::date;
  v_package public.packages;
  v_invoice public.invoices;
  v_billable public.trip_status[];
begin
  perform private.assert_ops();

  select pk.* into v_package
  from public.schedules s join public.packages pk on pk.id = s.package_id
  where s.patient_id = p_patient_id and s.active
  order by s.created_at desc limit 1;
  if not found then
    raise exception 'patient % has no active schedule (package)', p_patient_id using errcode = 'P0002';
  end if;

  select array_agg(x::public.trip_status) into v_billable
  from jsonb_array_elements_text((select value from public.app_settings where key = 'billable_trip_statuses')) x;

  select * into v_invoice from public.invoices where patient_id = p_patient_id and period_start = v_start for update;
  if found and v_invoice.status <> 'draft' then
    raise exception 'invoice for % is already %', v_start, v_invoice.status using errcode = '22023';
  end if;
  if not found then
    insert into public.invoices (patient_id, package_id, period_start, period_end, created_by)
    values (p_patient_id, v_package.id, v_start, v_end, auth.uid())
    returning * into v_invoice;
  else
    update public.invoices set package_id = v_package.id where id = v_invoice.id;
    delete from public.invoice_lines where invoice_id = v_invoice.id;
  end if;

  insert into public.invoice_lines (invoice_id, kind, trip_id, service_date, amount_paise)
  select v_invoice.id, k.kind, t.id, (t.scheduled_pickup_at at time zone 'Asia/Kolkata')::date, k.amount
  from public.trips t
  cross join lateral (values
    ('visit'::public.invoice_line_kind, v_package.price_per_visit_paise),
    ('fare'::public.invoice_line_kind, t.fare_amount_paise)
  ) k(kind, amount)
  where t.patient_id = p_patient_id
    and t.status = any (v_billable)
    and (t.scheduled_pickup_at at time zone 'Asia/Kolkata')::date between v_start and v_end
    and k.amount is not null and (k.kind = 'visit' or k.amount > 0);

  if v_package.monthly_fee_paise > 0 then
    insert into public.invoice_lines (invoice_id, kind, service_date, amount_paise)
    values (v_invoice.id, 'monthly_fee', v_start, v_package.monthly_fee_paise);
  end if;

  update public.invoices
  set total_paise = (select coalesce(sum(amount_paise), 0) from public.invoice_lines where invoice_id = v_invoice.id)
  where id = v_invoice.id;
  return v_invoice.id;
end;
$$;

-- Draft -> issued; tells the owner. An empty invoice cannot be issued.
create function public.ops_issue_invoice(p_invoice_id uuid)
returns void
language plpgsql volatile security definer set search_path = ''
as $$
declare
  v_invoice public.invoices;
begin
  perform private.assert_ops();
  select * into v_invoice from public.invoices where id = p_invoice_id for update;
  if not found then
    raise exception 'invoice % not found', p_invoice_id using errcode = 'P0002';
  end if;
  if v_invoice.status <> 'draft' or v_invoice.total_paise = 0 then
    raise exception 'only a non-empty draft can be issued' using errcode = '22023';
  end if;
  update public.invoices set status = 'issued', issued_at = now() where id = p_invoice_id;
  insert into public.notifications (recipient_id, channel, template, payload)
  select pa.user_id, 'push', 'invoice_issued',
         jsonb_build_object('invoice_id', p_invoice_id, 'total_paise', v_invoice.total_paise,
                            'period_start', v_invoice.period_start)
  from public.patient_access pa where pa.patient_id = v_invoice.patient_id and pa.access_level = 'owner';
end;
$$;

-- Invoices across patients for the ops console.
create function public.ops_invoices(p_month date default null)
returns table (
  invoice_id uuid, patient_id uuid, patient_name text, package_name text, period_start date,
  status public.invoice_status, total_paise integer, visits integer, fares_paise integer, paid_at timestamptz
)
language plpgsql stable security definer set search_path = ''
as $$
begin
  perform private.assert_ops();
  return query
  select i.id, p.id, p.full_name, pk.name, i.period_start, i.status, i.total_paise,
         (select count(*)::integer from public.invoice_lines l where l.invoice_id = i.id and l.kind = 'visit'),
         (select coalesce(sum(l.amount_paise), 0)::integer from public.invoice_lines l where l.invoice_id = i.id and l.kind = 'fare'),
         i.paid_at
  from public.invoices i
  join public.patients p on p.id = i.patient_id
  join public.packages pk on pk.id = i.package_id
  where p_month is null or i.period_start = date_trunc('month', p_month)::date
  order by i.period_start desc, p.full_name;
end;
$$;

-- Owner and editors see the bills (not drafts); viewers, companions and strangers do not.
create function public.family_invoices(p_patient_id uuid)
returns table (
  invoice_id uuid, period_start date, period_end date, status public.invoice_status, total_paise integer,
  package_name text, issued_at timestamptz, paid_at timestamptz, can_pay boolean
)
language plpgsql stable security definer set search_path = ''
as $$
begin
  if not private.can_edit_patient(p_patient_id) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return query
  select i.id, i.period_start, i.period_end, i.status, i.total_paise, pk.name, i.issued_at, i.paid_at,
         i.status = 'issued' and private.access_level_for(p_patient_id) = 'owner'
  from public.invoices i join public.packages pk on pk.id = i.package_id
  where i.patient_id = p_patient_id and i.status in ('issued', 'paid')
  order by i.period_start desc;
end;
$$;

create function public.family_invoice_lines(p_invoice_id uuid)
returns table (kind public.invoice_line_kind, service_date date, amount_paise integer)
language plpgsql stable security definer set search_path = ''
as $$
declare
  v_invoice public.invoices;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id;
  if not found or v_invoice.status not in ('issued', 'paid')
     or not (private.can_edit_patient(v_invoice.patient_id) or private.is_ops()) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return query
  select l.kind, l.service_date, l.amount_paise from public.invoice_lines l
  where l.invoice_id = p_invoice_id order by l.service_date nulls first, l.kind, l.id;
end;
$$;

-- Payments ------------------------------------------------------------------------

-- The owner starts paying an issued invoice. Returns the amount the payments
-- function asks the provider to collect. A started-but-unfinished attempt is reused.
create function public.payment_start(p_invoice_id uuid, p_provider text)
returns table (payment_id uuid, amount_paise integer, provider_order_id text)
language plpgsql volatile security definer set search_path = ''
as $$
declare
  v_invoice public.invoices;
  v_payment public.payments;
begin
  select * into v_invoice from public.invoices where id = p_invoice_id for update;
  if not found or private.access_level_for(v_invoice.patient_id) is distinct from 'owner' then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if v_invoice.status <> 'issued' then
    raise exception 'invoice is %', v_invoice.status using errcode = '22023';
  end if;
  select * into v_payment from public.payments
  where invoice_id = p_invoice_id and status = 'created' and provider = p_provider
  order by created_at desc limit 1;
  if not found then
    insert into public.payments (invoice_id, provider, amount_paise, created_by)
    values (p_invoice_id, p_provider, v_invoice.total_paise, auth.uid())
    returning * into v_payment;
  end if;
  return query select v_payment.id, v_payment.amount_paise, v_payment.provider_order_id;
end;
$$;

-- Service role: the provider created an order for this payment.
create function public.payment_set_order(p_payment_id uuid, p_provider_order_id text)
returns void
language plpgsql volatile security definer set search_path = ''
as $$
begin
  perform private.assert_service_role();
  update public.payments set provider_order_id = p_provider_order_id
  where id = p_payment_id and status = 'created' and provider_order_id is null;
  if not found then
    raise exception 'payment % cannot take an order id', p_payment_id using errcode = '22023';
  end if;
end;
$$;

-- Service role, from a verified provider webhook: the payment was captured.
-- Idempotent (providers retry webhooks). The amount must match (else the payment is
-- marked failed and 'amount_mismatch' returned); on a match the invoice is paid.
create function public.payment_captured(p_provider_order_id text, p_provider_payment_id text, p_amount_paise integer)
returns text
language plpgsql volatile security definer set search_path = ''
as $$
declare
  v_payment public.payments;
begin
  perform private.assert_service_role();
  select * into v_payment from public.payments where provider_order_id = p_provider_order_id for update;
  if not found then
    raise exception 'unknown order %', p_provider_order_id using errcode = 'P0002';
  end if;
  if v_payment.status = 'captured' then
    return 'already_captured';
  end if;
  if p_amount_paise is distinct from v_payment.amount_paise then
    -- Recorded, not raised: the failure must persist for ops to follow up.
    update public.payments set status = 'failed' where id = v_payment.id;
    return 'amount_mismatch';
  end if;
  update public.payments
  set status = 'captured', captured_at = now(), provider_payment_id = p_provider_payment_id
  where id = v_payment.id;
  update public.invoices set status = 'paid', paid_at = now() where id = v_payment.invoice_id and status = 'issued';
  return 'captured';
end;
$$;

-- The ops trip board also shows each trip's recorded fare (same function as 0500, one more column).
drop function public.ops_trip_board(timestamptz, timestamptz, public.trip_status[]);
create function public.ops_trip_board(
  p_from timestamptz,
  p_to timestamptz,
  p_statuses public.trip_status[] default null
)
returns table (
  trip_id uuid, scheduled_pickup_at timestamptz, scheduled_return_at timestamptz,
  status public.trip_status, status_before_issue public.trip_status,
  patient_id uuid, patient_name text, centre_name text, cluster_id uuid,
  companion_id uuid, companion_name text, schedule_id uuid,
  primary_companion_id uuid, primary_companion_name text,
  backup_companion_id uuid, backup_companion_name text,
  is_late boolean, updated_at timestamptz, fare_amount_paise integer
)
language plpgsql stable security definer set search_path = ''
as $$
declare
  v_late interval := make_interval(mins => private.setting_int('ops_late_after_minutes'));
begin
  perform private.assert_ops();
  if p_from is null or p_to is null or p_to < p_from
     or p_to - p_from > make_interval(days => private.setting_int('ops_board_max_days')) then
    raise exception 'invalid date range' using errcode = '22023',
      hint = 'from must be before to, within ops_board_max_days';
  end if;

  return query
  select t.id, t.scheduled_pickup_at, t.scheduled_return_at, t.status, t.status_before_issue,
         p.id, p.full_name, ce.name, ce.cluster_id, t.companion_id, cp.full_name, t.schedule_id,
         s.primary_companion_id, pp.full_name, s.backup_companion_id, bp.full_name,
         (t.status = 'scheduled' and now() > t.scheduled_pickup_at + v_late), t.updated_at, t.fare_amount_paise
  from public.trips t
  join public.patients p on p.id = t.patient_id
  join public.centres ce on ce.id = t.centre_id
  left join public.profiles cp on cp.id = t.companion_id
  left join public.schedules s on s.id = t.schedule_id
  left join public.profiles pp on pp.id = s.primary_companion_id
  left join public.profiles bp on bp.id = s.backup_companion_id
  where t.scheduled_pickup_at between p_from and p_to
    and (p_statuses is null or t.status = any (p_statuses))
  order by t.scheduled_pickup_at, p.full_name;
end;
$$;
revoke execute on function public.ops_trip_board(timestamptz, timestamptz, public.trip_status[]) from public, anon;
grant execute on function public.ops_trip_board(timestamptz, timestamptz, public.trip_status[]) to authenticated;

revoke execute on function
  public.ops_record_trip_fare(uuid, integer), public.ops_generate_invoice(uuid, date),
  public.ops_issue_invoice(uuid), public.ops_invoices(date),
  public.family_invoices(uuid), public.family_invoice_lines(uuid),
  public.payment_start(uuid, text), public.payment_set_order(uuid, text),
  public.payment_captured(text, text, integer)
from public, anon;
revoke execute on function public.payment_set_order(uuid, text), public.payment_captured(text, text, integer)
from authenticated;
grant execute on function public.payment_set_order(uuid, text), public.payment_captured(text, text, integer)
to service_role;
grant execute on function
  public.ops_record_trip_fare(uuid, integer), public.ops_generate_invoice(uuid, date),
  public.ops_issue_invoice(uuid), public.ops_invoices(date),
  public.family_invoices(uuid), public.family_invoice_lines(uuid), public.payment_start(uuid, text)
to authenticated;
